SourceCode.Declaration:
/// <summary>
/// designed by AVANADE
/// </summary>
class AVANumberSeqNiedaxSalesModule      extends NumberSeqApplicationModule
{
}

Method.Source:
public void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();
    datatype.parmDatatypeId(extendedTypeNum(AVAGAEBImportId));
    datatype.parmReferenceHelp("@NDX:NXASalesParameters");
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::Yes);
    datatype.parmWizardIsChangeUpAllowed(NoYes::Yes);
    datatype.parmSortField(1);
    datatype.parmWizardLowest(1);
    datatype.parmWizardHighest(9999);
    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);
}

/// <summary>
/// Add module of number sequences to map
/// </summary>
/// <param name = "numberSeqModuleNamesMap">Map of number sequences</param>
[SubscribesTo(classStr(NumberSeqGlobal), delegateStr(NumberSeqGlobal, buildModulesMapDelegate))]
public static void NumberSeqGlobal_buildModulesMapDelegate(Map numberSeqModuleNamesMap)
{
    NumberSeqGlobal::addModuleToMap(classnum(AVANumberSeqNiedaxSalesModule), numberSeqModuleNamesMap);
}
